     (select (other_instructions is not distinct from '["Not stated (typewritten)"]'::jsonb) from public.statement_requirements where id = 'd4e79cfc-8aa1-5c27-882b-3a9febbf3172'::uuid),
     (select (other_instructions is not distinct from '[]'::jsonb) from public.statement_requirements where id = 'd4e79cfc-8aa1-5c27-882b-3a9febbf3172'::uuid))
  )
select e.school, e.document, e.category,
       case when r.id is null then 'MISSING: no requirement with this id'
            when s.matches_old then 'READY'
            when s.matches_new then 'ALREADY: desired values already stored'
            else 'DRIFTED: neither the expected old nor the desired values'
       end as verdict
  from expected e
  left join state s on s.id = e.id
  left join public.statement_requirements r on r.id = e.id
union all
select 'ALL 28 DOCUMENTS' as school,
       (select count(*)::text from state where matches_old) || ' READY' as document,
       (select count(*)::text from state where matches_new) || ' ALREADY' as category,
       case when (select count(*) from state where matches_old) = 28
            then 'PROCEED'
            when (select count(*) from state where matches_new) = 28
            then 'ALREADY APPLIED -- nothing to do'
            else 'DO NOT APPLY -- read the rows above'
       end as verdict
 order by 1, 2;
